#include "newobject.h"
#include "newobjectpage.h"
#include "locationpage.h"
#include "document/document.h"
#include <QSaveFile>

using namespace Core::Internal::Wizards;

const char * NewObjectWizard::translation_context() {
    static const char ret[]={"new_object_dialog"};
    return ret;
}


NewObjectWizard::NewObjectWizard() {
    mDocument = nullptr;
    mParent   = nullptr;
    //dont allow to delete our wizard
    setAttribute(Qt::WA_DeleteOnClose, false);
    setOption(QWizard::NoBackButtonOnLastPage, true);
    mStartPage = new NewObjectPage;
    mStartPageId = addPage(mStartPage);
    mLocationPage = new LocationPage;
    mLocationPageId = addPage(mLocationPage);
    mSuccessPage = new QWizardPage;
    mSuccessPage->setTitle(tr("File was saved sucessfully"));
    mSuccessPage->setFinalPage(true);
    mSuccessPageId = addPage(mSuccessPage);
    mFailurePage = new QWizardPage;
    mFailurePage->setTitle(tr("Failed to write file", translation_context()));
    mFailurePage->setSubTitle(tr("Writing to disk failed.\n"
                                 "It may be caused by insufficiend space on disk,\n"
                                 "unsupported characters in file name, or insufficient\n"
                                 "permissions.\n\nTry to choose another location, file name\n"
                                 "or free some space on disk to continue.\n",
                                 translation_context()));
    mFailurePage->setFinalPage(true);
    mFailurePageId = addPage(mFailurePage);
    setStartId(mStartPageId);
}

NewObjectWizard::~NewObjectWizard() {
}

Core::Document * NewObjectWizard::newObject(DocumentKind * kind, const QString& preferredPath, Document * parent) {

    restart();

    NewObjectPage * no = (NewObjectPage*)mStartPage;
    no->setCurrentKind(kind);
    LocationPage  * lp = (LocationPage*)mLocationPage;
    lp->setPreferredPath(preferredPath);

    mDocument = nullptr;
    mParent   = parent;
    exec();
    Document * ret = mDocument;
    mDocument = nullptr;
    mParent   = nullptr;
    return ret;
}

